import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"全球化","description":"全球化","frontmatter":{"title":"全球化","description":"全球化","date":"2026-05-29T00:00:00.000Z","category":"置身事内","tags":["宏观观察"],"order":3},"headers":[],"relativePath":"articles/zstn/macro/global-economics.md","filePath":"articles/zstn/macro/global-economics.md","articleMeta":{"updated":"2026-05-29","words":440,"minutes":1}}`),a={name:`articles/zstn/macro/global-economics.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h2 id="海上邻居" tabindex="-1">海上邻居 <a class="header-anchor" href="#海上邻居" aria-label="Permalink to “海上邻居”">​</a></h2><p>集装箱发明之后，距离已经不值钱了，整个世界都变成了地中海。</p><p>统一规格的铁盒子，从工厂流水线直接装上卡车，再转运到远洋巨轮，全程无需拆箱、无需人力搬运，损耗率压到 1% 以下，海运成本直接暴跌 90%。</p><p>海运最恐怖的地方在于：越远，反而越能摊薄成本。</p><p>一艘船装几万个集装箱，一趟航线跑下来，每斤牛肉分摊到的运费，可能低到你难以想象。真正贵的，反而不是横跨太平洋，而是从港口到你家门口最后那几百公里。</p><p>所以现代世界出现了一个非常诡异的现象：</p><p>上海和布宜诺斯艾利斯，可能比中国某些内陆小县城和沿海城市更 “近”。</p><p>不是地理上近，而是经济上近。</p><h2 id="贸易顺差和汇率" tabindex="-1">贸易顺差和汇率 <a class="header-anchor" href="#贸易顺差和汇率" aria-label="Permalink to “贸易顺差和汇率”">​</a></h2><p>其实正常情况来讲，一个国家如果巨额贸易顺差，会推动本币升值，只要人民币大涨了，出口的价格贵了，不好卖了，就会抑制出口，从而缩小贸易顺差。但我们现在有个特殊情况，很多人做外贸赚了外汇他不转回来换人民币，之前彭博社不是算过一笔账嘛，有6000-8000亿美元离岸外汇跑去海外投资了，所以就导致明明巨额贸易顺差，但人民币又不升值的奇异现象。</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};